#include <vector>
#include <unordered_map>
#include <queue>

using namespace std;

class Solution {
public:
    vector<int> rearrangeBarcodes(vector<int>& barcodes) {
        unordered_map<int, int> count;
        for (int b : barcodes) count[b]++;

        priority_queue<pair<int, int>> pq;
        for (auto& [num, freq] : count)
            pq.push({freq, num});

        vector<int> res;
        while (!pq.empty()) {
            auto [f1, n1] = pq.top(); pq.pop();
            if (res.empty() || res.back() != n1) {
                res.push_back(n1);
                if (--f1 > 0) pq.push({f1, n1});
            } else {
                auto [f2, n2] = pq.top(); pq.pop();
                res.push_back(n2);
                if (--f2 > 0) pq.push({f2, n2});
                pq.push({f1, n1});
            }
        }

        return res;
    }
};
